@GameTestHolder(HeavenlyRestriction.ID) @PrefixGameTestTemplate(false)
public final class ExponentiationGameTests {
    private static double boosted(double n){return Math.pow(n,1.2);}
    private static ManasSkillInstance equip(LivingEntity p){RestrictionData.learnReward(p,HeavenlyRestriction.EXPONENTIATION.get());var i=SkillAPI.getSkillsFrom(p).getSkill(HeavenlyRestriction.EXPONENTIATION.get()).orElseThrow();i.setMastery(0);TensuraStorages.getAbilityFrom(p).setAbilitySlot(0,0,i.getSkill(),0);return i;}
    private static void reset(ServerPlayer p,Runnable task){try(var scope=ExponentiationContext.raw(p,ExponentiationContext.RESTORE)){task.run();}}
    @GameTest(template="empty",timeoutTicks=100)
    public static void activePresetLearningAndTemporaryStatsAreExact(GameTestHelper h){var p=player(h);p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);var i=equip(p);h.assertTrue(Exponentiation.active(p),"Slotted learned skill inactive");for(int n=0;n<30;n++)near(h,p.getMaxHealth(),boosted(100),"Repeated stat reads compounded");near(h,p.getAttribute(Attributes.MAX_HEALTH).getBaseValue(),100,"Saved base was mutated");TensuraStorages.getAbilityFrom(p).setAbilitySlot(0,0,null,0);near(h,p.getMaxHealth(),100,"Unslotted bonus remained");TensuraStorages.getAbilityFrom(p).setAbilitySlot(1,0,i.getSkill(),0);h.assertTrue(!Exponentiation.active(p),"Inactive preset activated passive");TensuraStorages.getAbilityFrom(p).setAbilitySlot(0,0,i.getSkill(),0);i.setMastery(-1);h.assertTrue(!Exponentiation.active(p),"Unlearned passive activated");h.assertTrue(!ChainedReincarnation.blocked(i.getSkill(),p),"No-cost skill incorrectly blacklisted");h.assertTrue(io.github.manasmods.tensura.menu.ReincarnationMenu.getSkillPool().contains(i.getSkill()),"Reincarnation pool missing Exponentiation");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void nonMovementSpeedsUsePowerAndMovementIsUntouched(GameTestHelper h){var p=player(h);p.getAttribute(Attributes.ATTACK_SPEED).setBaseValue(4);p.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(.25);p.getAttribute(Attributes.JUMP_STRENGTH).setBaseValue(.7);p.getAttribute(TensuraAttributes.CHANT_SPEED).setBaseValue(3);equip(p);near(h,p.getAttributeValue(Attributes.ATTACK_SPEED),boosted(4),"Attack speed excluded");near(h,p.getAttributeValue(TensuraAttributes.CHANT_SPEED),boosted(3),"Chant speed excluded");near(h,p.getAttributeValue(Attributes.MOVEMENT_SPEED),.25,"Movement speed changed");near(h,p.getAttributeValue(Attributes.JUMP_STRENGTH),.7,"Jump changed");p.setOnGround(true);p.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.DIAMOND_PICKAXE));float speed;try(var scope=ExponentiationContext.raw(p,ExponentiationContext.RESTORE)){TensuraStorages.getAbilityFrom(p).setAbilitySlot(0,0,null,0);speed=p.getDigSpeed(Blocks.STONE.defaultBlockState(),p.blockPosition());TensuraStorages.getAbilityFrom(p).setAbilitySlot(0,0,HeavenlyRestriction.EXPONENTIATION.get(),0);}near(h,p.getDigSpeed(Blocks.STONE.defaultBlockState(),p.blockPosition()),boosted(speed),"Final mining speed was not amplified once");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void realMeleeAndSkillDamageAmplifyOnceAndOnlyForTheAttacker(GameTestHelper h){var p=player(h);var e=target(h,p.position().add(2,0,0));e.getAttribute(Attributes.ARMOR).setBaseValue(0);p.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(10);equip(p);reset(p,()->p.setHealth(20));float before=e.getHealth();e.invulnerableTime=0;e.hurt(p.damageSources().playerAttack(p),10);near(h,before-e.getHealth(),boosted(10),"Flat skill damage power boost");e.setHealth(1024);e.invulnerableTime=0;try(var scope=ExponentiationContext.raw(p,ExponentiationContext.DAMAGE)){near(h,p.getAttributeValue(Attributes.ATTACK_DAMAGE),10,"Formula inputs were already amplified");}p.setSprinting(false);p.setOnGround(true);try{var field=LivingEntity.class.getDeclaredField("attackStrengthTicker");field.setAccessible(true);field.setInt(p,100);}catch(ReflectiveOperationException failure){throw new IllegalStateException(failure);};p.attack(e);near(h,1024-e.getHealth(),boosted(10),"Native melee double-dipped attack attribute");var receiving=target(h,p.position().add(5,0,0));equip(receiving);float hp=receiving.getHealth();receiving.hurt(receiving.damageSources().genericKill(),3);near(h,hp-receiving.getHealth(),3,"Unattributed incoming damage was amplified");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void hpShpAndEnergyGainsAreDeltasWithNormalCosts(GameTestHelper h){var p=player(h);p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);p.getAttribute(TensuraAttributes.MAX_SPIRITUAL_HEALTH).setBaseValue(100);equip(p);var energy=TensuraStorages.getExistenceFrom(p);reset(p,()->{p.setHealth(20);energy.setSpiritualHealth(20);energy.setAura(1000);energy.setMagicule(1000);});p.heal(5);near(h,p.getHealth(),20+boosted(5),"HP healing was not 5^1.2");energy.setSpiritualHealth(25);near(h,energy.getSpiritualHealth(),20+boosted(5),"SHP healing was not 5^1.2");energy.setAura(1005);near(h,energy.getAura(),1000+boosted(5),"Aura gain was not a delta");energy.setMagicule(1005);near(h,energy.getMagicule(),1000+boosted(5),"Magicule gain was not a delta");EnergyHelper.isOutOfEnergy(p,10,20);near(h,energy.getAura(),990+boosted(5),"Aura bill changed");near(h,energy.getMagicule(),980+boosted(5),"Magicule bill changed");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void healingAfterSchemaAndUnequipCleanupDoNotCompound(GameTestHelper h){var p=player(h);p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(200);equip(p);RestrictionData.learnReward(p,HeavenlyRestriction.SCHEMA.get());var schema=SkillAPI.getSkillsFrom(p).getSkill(HeavenlyRestriction.SCHEMA.get()).orElseThrow();schema.setMastery(0);h.assertTrue(SchemaArt.save(p,new int[]{3,0,0,0,0,0},0),"Schema build failed");schema.onToggleOn(p);reset(p,()->p.setHealth(20));p.heal(10);near(h,p.getHealth(),20+boosted(12),"Schema's final 12 healing must become 12^1.2");Exponentiation.tick(new net.neoforged.neoforge.event.tick.EntityTickEvent.Post(p));TensuraStorages.getAbilityFrom(p).setAbilitySlot(0,0,null,0);Exponentiation.tick(new net.neoforged.neoforge.event.tick.EntityTickEvent.Post(p));near(h,p.getHealth(),20+boosted(12),"Unequip changed HP below normal capacity over-cap HP");near(h,p.getAttribute(Attributes.MAX_HEALTH).getBaseValue(),200,"Cleanup changed base");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void directSpiritualDamageUsesFinalResistedAmount(GameTestHelper h){var p=player(h);var target=target(h,p.position().add(2,0,0));var energy=TensuraStorages.getExistenceFrom(target);target.getAttribute(TensuraAttributes.MAX_SPIRITUAL_HEALTH).setBaseValue(10000);energy.setSpiritualHealth(10000);equip(p);boolean hit=io.github.manasmods.tensura.damage.TensuraDamageHelper.directSpiritualHurt(target,p,p.damageSources().playerAttack(p),20,.5f);h.assertTrue(hit,"Direct spiritual attack failed");near(h,energy.getSpiritualHealth(),10000-boosted(10),"20 × 50% resistance should become 10^1.2, not 20^1.2");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void chanceLimitsFractionsAndCooldownsAreRetained(GameTestHelper h){var p=player(h);equip(p);p.getAttribute(TensuraAttributes.AUTO_MELEE_DODGE_CHANCE).setBaseValue(100);p.getAttribute(TensuraAttributes.GRAVITY_BOOST).setBaseValue(3);near(h,p.getAttributeValue(TensuraAttributes.AUTO_MELEE_DODGE_CHANCE),100,"Dodge chance exceeded 100%");near(h,p.getAttributeValue(TensuraAttributes.GRAVITY_BOOST),boosted(3),"Gravity elemental damage was mistaken for movement");near(h,Exponentiation.amplify(.5),.5,"Beneficial-only lens reduced a fraction");var i=SkillAPI.getSkillsFrom(p).getSkill(HeavenlyRestriction.EXPONENTIATION.get()).orElseThrow();i.setCoolDown(200,0);h.assertTrue(i.getCoolDown(0)==200,"Cooldown changed");h.assertTrue(Double.isFinite(Exponentiation.amplify(Double.MAX_VALUE)),"Overflow reached infinity");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void learningMasteryXpAndLootAreFinalGains(GameTestHelper h){var p=player(h);equip(p);SchemaArt.discover(p);var i=SkillAPI.getSkillsFrom(p).getSkill(HeavenlyRestriction.SCHEMA.get()).orElseThrow();HeavenlyRestriction.SCHEMA.get().addLearnPoint(i,p,0,3);near(h,i.getMastery(),-1000+boosted(3),"Learning gain not 3^1.2");i.setMastery(0);HeavenlyRestriction.SCHEMA.get().addMasteryPoint(i,p,3);near(h,i.getMastery(),boosted(3),"Mastery gain not 3^1.2");var xp=new net.neoforged.neoforge.event.entity.player.PlayerXpEvent.XpChange(p,3);ExponentiationRewards.xp(xp);h.assertTrue(xp.getAmount()==(int)boosted(3),"XP gain not amplified");var item=new net.minecraft.world.entity.item.ItemEntity(h.getLevel(),p.getX(),p.getY(),p.getZ(),new ItemStack(Items.COAL,5));var drops=new ArrayList<net.minecraft.world.entity.item.ItemEntity>();drops.add(item);ExponentiationRewards.block(new net.neoforged.neoforge.event.level.BlockDropsEvent(h.getLevel(),p.blockPosition(),Blocks.COAL_ORE.defaultBlockState(),null,drops,p,new ItemStack(Items.DIAMOND_PICKAXE)));h.assertTrue(item.getItem().getCount()==(int)boosted(5),"Final loot stack was not amplified");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void epPayoutRaisesTotalAwardOnce(GameTestHelper h){var p=player(h);var victim=target(h,p.position().add(3,0,0));p.getAttribute(TensuraAttributes.AURA_GAIN).setBaseValue(100);p.getAttribute(TensuraAttributes.MAGICULE_GAIN).setBaseValue(100);double a=EnergyHelper.getBaseMaxAura(p),m=EnergyHelper.getBaseMaxMagicule(p);io.github.manasmods.tensura.handler.DeathHandler.gainEPEntity(p,victim,boosted(9));double da=EnergyHelper.getBaseMaxAura(p)-a,dm=EnergyHelper.getBaseMaxMagicule(p)-m;p.getAttribute(TensuraAttributes.MAX_AURA).setBaseValue(a);p.getAttribute(TensuraAttributes.MAX_MAGICULE).setBaseValue(m);equip(p);io.github.manasmods.tensura.handler.DeathHandler.gainEPEntity(p,victim,9);near(h,EnergyHelper.getBaseMaxAura(p)-a,da,"Consolidated EP aura award compounded gain multiplier");near(h,EnergyHelper.getBaseMaxMagicule(p)-m,dm,"Consolidated EP magicule award compounded gain multiplier");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void exportExactAttributePolicyAndVerifyMovementExclusions(GameTestHelper h){var previewOwner=player(h);equip(previewOwner);var rows=new com.google.gson.JsonArray();for(var entry:BuiltInRegistries.ATTRIBUTE.entrySet()){var a=entry.getValue();var rule=Exponentiation.rule(a);var row=new com.google.gson.JsonObject();row.addProperty("id",entry.getKey().location().toString());row.addProperty("name",a.getDescriptionId());row.addProperty("included",rule.included());row.addProperty("role",rule.role());row.addProperty("reason",rule.exclusion());row.addProperty("can_change",rule.included() && (!(a instanceof RangedAttribute r) || r.getMaxValue()>1));if(rule.included() && (!(a instanceof RangedAttribute r) || r.getMaxValue()>1)){var instance=new AttributeInstance(net.minecraft.core.Holder.direct(a),ignored->{});((io.github.manasmods.tensura.registry.attribute.TensuraAttributeInstance)instance).tensura$setOwner(previewOwner);instance.setBaseValue(3);double before;try(var raw=ExponentiationContext.raw(previewOwner,ExponentiationContext.ATTRIBUTES)){before=instance.getValue();}row.addProperty("before",before);row.addProperty("after",instance.getValue());}rows.add(row);}try{var file=java.nio.file.Path.of(System.getProperty("java.io.tmpdir"),"exponentiation-attribute-audit.json");java.nio.file.Files.writeString(file,new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(rows));}catch(java.io.IOException failure){throw new IllegalStateException(failure);}h.assertTrue(!Exponentiation.rule(Attributes.MOVEMENT_SPEED.value()).included() && !Exponentiation.rule(Attributes.SNEAKING_SPEED.value()).included() && Exponentiation.rule(Attributes.ATTACK_SPEED.value()).included(),"Speed exclusion policy differs from requested movement-only rule");h.succeed();}
    private static void regen(String method,Class<?>[] types,Object... args){try{var m=io.github.manasmods.tensura.storage.ep.ExistenceStorage.class.getDeclaredMethod(method,types);m.setAccessible(true);m.invoke(null,args);}catch(ReflectiveOperationException failure){throw new IllegalStateException(failure);}}
    @GameTest(template="empty",timeoutTicks=100)
    public static void nativeRegenerationAndSleepAmplifyOnlyTheCompletedGain(GameTestHelper h){var p=player(h);p.getAttribute(TensuraAttributes.MAX_AURA).setBaseValue(1000);p.getAttribute(TensuraAttributes.MAX_SPIRITUAL_HEALTH).setBaseValue(1000);p.getAttribute(TensuraAttributes.AURA_REGENERATION_MULTIPLIER).setBaseValue(3);p.getAttribute(TensuraAttributes.SPIRITUAL_HEALTH_REGENERATION).setBaseValue(3);equip(p);var energy=TensuraStorages.getExistenceFrom(p);double base=EnergyHelper.CONFIG.baseAuraRegen,sleep=EnergyHelper.CONFIG.sleepModeAura;try{EnergyHelper.CONFIG.baseAuraRegen=2;EnergyHelper.CONFIG.sleepModeAura=.01;reset(p,()->{energy.setAura(100);energy.setSpiritualHealth(100);});regen("handleAuraRegen",new Class<?>[]{io.github.manasmods.tensura.storage.ep.IExistence.class,LivingEntity.class,double.class},energy,p,EnergyHelper.getMaxAura(p));near(h,energy.getAura(),100+boosted(6),"Native 2 × 3 aura regen did not become 6^1.2");energy.setSleepModeTime(200);reset(p,()->energy.setAura(100));regen("handleAuraRegen",new Class<?>[]{io.github.manasmods.tensura.storage.ep.IExistence.class,LivingEntity.class,double.class},energy,p,EnergyHelper.getMaxAura(p));near(h,energy.getAura(),100+boosted(16),"Sleep reused amplified maximum and amplified it twice");regen("handleSpiritualHealthRegen",new Class<?>[]{net.minecraft.server.MinecraftServer.class,LivingEntity.class,io.github.manasmods.tensura.storage.ep.IExistence.class},p.server,p,energy);near(h,energy.getSpiritualHealth(),100+boosted(3),"Native SHP regen compounded or clamped to an unboosted maximum");}finally{EnergyHelper.CONFIG.baseAuraRegen=base;EnergyHelper.CONFIG.sleepModeAura=sleep;}h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void fusionTransfersDoNotBecomeHealingOrReapplyCapacity(GameTestHelper h){var p=player(h);var host=target(h,p.position().add(3,0,0));p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);host.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);equip(p);RestrictionData.learnReward(p,HeavenlyRestriction.FUSION.get());TensuraStorages.getExistenceFrom(host).setPermanentOwner(p.getUUID());reset(p,()->p.setHealth(50));host.setHealth(50);double ep=EnergyHelper.getMaxEP(p)+EnergyHelper.getMaxEP(host);afterTracking(h,List.of(host),()->{try(var nativeCallback=ChainedContext.ability(p,HeavenlyRestriction.FUSION.get())){h.assertTrue(dev.heavenlyrestriction.fusion.Fusion.fuseSubordinate(p,host),"Fusion failed");}try{near(h,p.getMaxHealth(),boosted(100)+100,"Fusion capacity amplified twice");near(h,p.getHealth(),100,"Transferred HP was interpreted as healing");double actual=EnergyHelper.getMaxEP(p),expected=1.5*ep;h.assertTrue(Math.abs(actual-expected)/expected<1e-6,"Fusion EP solver compounded Exponentiation");}finally{try(var nativeCallback=ChainedContext.ability(p,HeavenlyRestriction.FUSION.get())){dev.heavenlyrestriction.fusion.Fusion.end(p,"Test");}}near(h,p.getMaxHealth(),boosted(100),"Fusion permanently changed capacity");h.succeed();});}

    @GameTest(template="empty",timeoutTicks=100)
    public static void capacitiesStayNormalAndOldReservesMigrate(GameTestHelper h){var p=player(h);p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);p.getAttribute(TensuraAttributes.MAX_SPIRITUAL_HEALTH).setBaseValue(100);p.getAttribute(TensuraAttributes.MAX_AURA).setBaseValue(1000);p.getAttribute(TensuraAttributes.MAX_MAGICULE).setBaseValue(1000);equip(p);near(h,p.getMaxHealth(),boosted(100),"HP capacity missing");near(h,EnergyHelper.getMaxAura(p),1000,"Aura capacity changed");near(h,EnergyHelper.getMaxMagicule(p),1000,"Magicule capacity changed");var e=TensuraStorages.getExistenceFrom(p);reset(p,()->{e.setAura(5000);e.setMagicule(5000);e.setSpiritualHealth(500);});p.getPersistentData().putBoolean("heavenlyrestriction.exponentiation_active",true);Exponentiation.tick(new net.neoforged.neoforge.event.tick.EntityTickEvent.Post(p));near(h,e.getAura(),1000,"Old aura did not clamp");near(h,e.getMagicule(),1000,"Old magicules did not clamp");near(h,e.getSpiritualHealth(),boosted(100),"SHP was incorrectly clamped to unboosted capacity");h.succeed();}

    @GameTest(template="empty",timeoutTicks=100)
    public static void oxygenCapacityPersistsWithoutShortOverflowAndDirectGrantsStayNormal(GameTestHelper h){var p=player(h);equip(p);near(h,p.getMaxAirSupply(),(int)(20*boosted(15)),"Oxygen capacity not amplified");p.setAirSupply(400);var tag=new net.minecraft.nbt.CompoundTag();p.saveWithoutId(tag);h.assertTrue(tag.getInt("heavenlyrestriction.exponentiation_air")==400,"Large air pool truncated on save");p.setAirSupply(0);p.load(tag);near(h,p.getAirSupply(),400,"Large air pool truncated on reload");p.getAttribute(TensuraAttributes.AURA_GAIN).setBaseValue(3);p.getAttribute(TensuraAttributes.MAGICULE_GAIN).setBaseValue(3);double a=EnergyHelper.getBaseMaxAura(p),m=EnergyHelper.getBaseMaxMagicule(p);EnergyHelper.gainAura(p,3,EnergyHelper.GainType.MAX);EnergyHelper.gainMagicule(p,3,EnergyHelper.GainType.MAX);near(h,EnergyHelper.getBaseMaxAura(p)-a,3,"Direct permanent aura grant was multiplied");near(h,EnergyHelper.getBaseMaxMagicule(p)-m,3,"Direct permanent magicule grant was multiplied");near(h,p.getAttributeValue(TensuraAttributes.AURA_GAIN),3,"Aura gain attribute was amplified");near(h,p.getAttributeValue(TensuraAttributes.MAGICULE_GAIN),3,"Magicule gain attribute was amplified");Exponentiation.tick(new net.neoforged.neoforge.event.tick.EntityTickEvent.Post(p));TensuraStorages.getAbilityFrom(p).setAbilitySlot(0,0,null,0);Exponentiation.tick(new net.neoforged.neoforge.event.tick.EntityTickEvent.Post(p));near(h,p.getAirSupply(),300,"Unequip left excess oxygen");h.succeed();}

}
